def transform(grid):
    from collections import Counter
    bg=Counter(c for r in grid for c in r).most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg]
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    g=[row[:] for row in grid]
    def fill(cells_to_fill):
        for r,c in cells_to_fill:
            if g[r][c]==bg: g[r][c]=2
    perim={(r,c) for r in (r0,r1) for c in range(c0,c1+1)} | {(r,c) for r in range(r0,r1+1) for c in (c0,c1)}
    fill(perim)
    for c in range(c0+1,c1):
        rows_in=[r for r in range(r0+1,r1) if grid[r][c]!=bg]
        if len(rows_in)>=2:
            fill({(r,c) for r in range(r0,r1+1)})
    for r in range(r0+1,r1):
        cols_in=[c for c in range(c0+1,c1) if grid[r][c]!=bg]
        if len(cols_in)>=2:
            fill({(r,c) for c in range(c0,c1+1)})
    return g
